#include "userland/common/command.h"
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
int main(int argc,char**argv){const char*del="\t";int serial=0,i=1,status=0;if(i<argc&&!strcmp(argv[i],"-s")){serial=1;i++;}if(i<argc&&!strcmp(argv[i],"-d")&&++i<argc)del=argv[i++];if(i==argc){argv[--i]=(char*)"-";argc=i+1;}if(serial){for(;i<argc;i++){FILE*f=!strcmp(argv[i],"-")?stdin:fopen(argv[i],"r");char*l=NULL;size_t c=0;long n;size_t di=0;int first=1;if(!f){command_error("paste",argv[i]);status=1;continue;}while((n=command_read_line(f,&l,&c))>0){if(n&&l[n-1]=='\n')n--;if(!first)putchar(del[di++%strlen(del)]);fwrite(l,1,(size_t)n,stdout);first=0;}putchar('\n');free(l);if(f!=stdin)fclose(f);}return status||ferror(stdout);}else{int count=argc-i,j,active;FILE**fs=calloc((size_t)count,sizeof(*fs));char**ls=calloc((size_t)count,sizeof(*ls));size_t*cs=calloc((size_t)count,sizeof(*cs));if(!fs||!ls||!cs)return 1;for(j=0;j<count;j++){fs[j]=!strcmp(argv[i+j],"-")?stdin:fopen(argv[i+j],"r");if(!fs[j]){command_error("paste",argv[i+j]);return 1;}}do{active=0;for(j=0;j<count;j++){long n=command_read_line(fs[j],&ls[j],&cs[j]);if(n>0){active=1;if(ls[j][n-1]=='\n')n--;fwrite(ls[j],1,(size_t)n,stdout);}if(j+1<count)putchar(del[(size_t)j%strlen(del)]);}if(active)putchar('\n');}while(active);for(j=0;j<count;j++){free(ls[j]);if(fs[j]!=stdin)fclose(fs[j]);}free(fs);free(ls);free(cs);return ferror(stdout);}}
